    try { data = fs.readFileSync(DB_PATH); } catch { return; }
    const h = this._hash(data);
    if (h === this._lastHash) return;
    if (this._txnDepth > 0) { this._pendingReload = true; return; }
    this._doReload(data);
  }

  _doReload(data) {
    this._db.close();
    this._db = new this._SQL.Database(data);
    this._db.exec('PRAGMA foreign_keys = ON');
    this._lastHash = this._hash(data);
